from __future__ import annotations

import pybamm


class TestSymbolDomainsSetterDefUseIntersectionQA:
    def _make_symbol(self, name, domain):
        symbol = pybamm.Symbol(name, domain=domain)
        assert symbol.domain == [domain]
        return symbol

